+using System.Runtime.InteropServices;
+
+namespace Korda.Database.Internal;
+
+// Independent count-only diagnostic. Never included in an ordinary candidate.
+internal static partial class ParityLeaseObserver
+{
+    private static long _cursors;
+    internal static ulong NextCursor() => 0x7000000000000000UL | (ulong)Interlocked.Increment(ref _cursors);
+
+    [LibraryImport("parity_sampler", EntryPoint = "parity_mark")]
+    private static partial void NativeMark(ulong request, uint batch, ushort phase, ushort kind, ulong count, ulong bytes);
+
+    internal static void Mark(ulong cursor, long generation, ushort phase, ulong count = 0, ulong bytes = 0)
+        => NativeMark(cursor, checked((uint)generation), phase, 1, count, bytes);
+}
